using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Identity;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;using OperationsRequests.Data;using OperationsRequests.Domain;using OperationsRequests.Services;namespace OperationsRequests.Pages;[Authorize]public class IndexModel(ApplicationDbContext db,UserManager<ApplicationUser> users,ScopeService scope):PageModel{public List<TrainingRequest> Requests{get;set;}=[];public Dictionary<RequestStatus,int> Counts{get;set;}=[];public async Task OnGetAsync(){var u=await users.GetUserAsync(User)??throw new UnauthorizedAccessException();var roles=await users.GetRolesAsync(u);var all=await db.TrainingRequests.Include(x=>x.Site).ThenInclude(x=>x.Territory).ThenInclude(x=>x.Country).Include(x=>x.RequestedBy).OrderByDescending(x=>x.CreatedAt).ToListAsync();Requests=all.Where(x=>scope.CanView(x,u,roles)).ToList();Counts=Requests.GroupBy(x=>x.Status).ToDictionary(x=>x.Key,x=>x.Count());}}
